-- Offline tests of the SDK Routes library (dp_routes.lua) on core-baked golden layouts.
--   lua Tools/routes-offline/test_routes.lua
-- Fixtures: fixtures/cchouse_rects.lua (CrashCourse house test, core-baked openings) and
-- fixtures/house3_rects.lua (My House 3, a real RoomPlan scan), both generated by
-- Tools/openings-e2e-offline. Also checks DreamParkLuaRoutes.cs embeds the current Lua.
local HERE = (arg and arg[0] or ''):match('^(.*)/[^/]*$') or '.'
local R = dofile(HERE .. '/dp_routes.lua')
local fails, passes = 0, 0
local function check(c, msg) if c then passes = passes + 1 print('ok   ' .. msg) else fails = fails + 1 print('FAIL ' .. msg) end end

-- ── the house's walls (venue_plan.py WALLS_RAW minus its doors) ─────────────
local DOORS = { {4.0,1.0,4.0,1.9}, {5.2,1.5,5.2,2.4}, {5.2,5.0,5.2,5.9}, {4.0,5.05,4.0,5.95}, {1.5,5.0,2.4,5.0}, {6.3,8.5,7.2,8.5}, {4.15,0,5.05,0} }
local RAW = { {0,0,8.2,0}, {0,8.5,8.2,8.5}, {0,0,0,8.5}, {8.2,0,8.2,8.5}, {4.0,0,4.0,8.5}, {5.2,0,5.2,8.5}, {0,5.0,4.0,5.0}, {0.5,5.0,0.5,8.5},
              {5.2,3.5,8.2,3.5}, {5.2,4.5,8.2,4.5}, {4.0,6.0,5.2,6.0}, {0,18.6,8.2,18.6}, {0,8.5,0,18.6}, {8.2,8.5,8.2,18.6} }
local WALLS = {}
for _, w in ipairs(RAW) do
    local segs = { w }
    for _, d in ipairs(DOORS) do
        local nxt = {}
        for _, s in ipairs(segs) do
            local vertical = s[1] == s[3]
            local on = vertical and d[1] == d[3] and math.abs(d[1] - s[1]) < 1e-6 or (not vertical and d[2] == d[4] and math.abs(d[2] - s[2]) < 1e-6)
            if not on then nxt[#nxt + 1] = s
            else
                local a0, a1 = vertical and s[2] or s[1], vertical and s[4] or s[3]
                local d0, d1 = vertical and d[2] or d[1], vertical and d[4] or d[3]
                local function mk(u, v) return vertical and { s[1], u, s[1], v } or { u, s[2], v, s[2] } end
                if d0 > a0 then nxt[#nxt + 1] = mk(a0, math.min(d0, a1)) end
                if d1 < a1 then nxt[#nxt + 1] = mk(math.max(d1, a0), a1) end
            end
        end
        segs = nxt
    end
    for _, s in ipairs(segs) do WALLS[#WALLS + 1] = s end
end
local function seg_hit(px, pz, qx, qz, ax, az, bx, bz)
    local function cr(ox, oz, ux, uz, vx, vz) return (ux - ox) * (vz - oz) - (uz - oz) * (vx - ox) end
    return cr(ax, az, bx, bz, px, pz) * cr(ax, az, bx, bz, qx, qz) < 0 and cr(px, pz, qx, qz, ax, az) * cr(px, pz, qx, qz, bx, bz) < 0
end
local function crossings(pts)
    local x = 0
    for i = 2, #pts do for _, w in ipairs(WALLS) do if seg_hit(pts[i-1].x, pts[i-1].z, pts[i].x, pts[i].z, w[1], w[2], w[3], w[4]) then x = x + 1 end end end
    return x
end

-- ── stops: one attraction filling each rect (what the Arena seats), from core's data ──
local function stops_from(rects, names)
    local out = {}
    for _, r in ipairs(rects) do
        if names == nil or names[r.id] then
            out[#out + 1] = { id = 's_' .. r.id, name = 'A_Test#' .. r.id, cx = r.cx, cz = r.cz, yaw = r.yaw, W = r.W, L = r.L,
                              flex = true, rect = { id = r.id, opens = r.opens } }
        end
    end
    return out
end
local HOUSE = dofile(HERE .. '/fixtures/cchouse_rects.lua')
local H3 = dofile(HERE .. '/fixtures/house3_rects.lua')

-- 1. point-to-point routes through doors
do
    local P = stops_from(HOUSE)
    local r = R.route(P, 2.5, 2.5, 6.7, 1.5)                     -- Living centre -> Den centre
    check(r.ok and r.source == 'doors', 'Living -> Den routes over the door graph (' .. tostring(r.source) .. ')')
    check(r.hops == 2, 'through 2 doorways (Living|Hall, Hall|Den): ' .. tostring(r.hops))
    check(crossings(r.pts) == 0, string.format('crosses no wall (%.2f m, %d points)', r.len, #r.pts))
    local r2 = R.route(P, 2.5, 2.5, 4.0, 11.0)                    -- Living -> YardA via the back door
    check(r2.ok and crossings(r2.pts) == 0, string.format('Living -> YardA: %d doors, %.2f m, no wall crossed', r2.hops, r2.len))
    local yard = false
    for _, d in ipairs(r2.doors) do if (d.from == 'Kitchen' and d.to == 'YardA') or (d.from == 'YardA' and d.to == 'Kitchen') then yard = true end end
    check(yard, 'the yard is reached through the back door (D6)')
    local r3 = R.route(P, 4.0, 11.0, 3.0, 16.0)                   -- YardA -> YardB (10 cm apart, same room)
    check(r3.ok and r3.hops >= 1, 'YardA -> YardB connected (same-room rects 10 cm apart): ' .. tostring(r3.why or 'ok'))
    local none = R.route({}, 0, 0, 3, 4)
    check(none.ok and none.source == 'straight' and math.abs(none.len - 5) < 1e-9, 'no park data: a straight line')
    local out = R.route(P, -5, -5, 2.5, 2.5)
    check(out.source == 'straight' and out.why ~= nil, 'an end outside every rect: straight, with why')
end

-- 2. a tour of the whole house: every link through doorways, no wall crossed
local function tour(P, opts)
    local plan, why = R.plan(P, nil, opts)
    return plan, why
end
do
    local P = stops_from(HOUSE)
    local t0 = os.clock()
    local plan, why = tour(P, {})
    check(plan ~= nil, 'house tour planned: ' .. tostring(why))
    if plan then
        local names, walk, xs = {}, 0, 0
        for _, p in ipairs(plan.order) do names[#names + 1] = p.rect.id end
        for _, l in ipairs(plan.links) do walk = walk + (l.len or 1e6) xs = xs + crossings(l.pts or {}) end
        print(string.format('     order %s, walk %.2f m (cost %.2f), %.0f ms', table.concat(names, ' > '), walk, plan.cost, (os.clock() - t0) * 1000))
        check(#plan.order == #P, 'every stop visited (' .. #plan.order .. '/' .. #P .. ')')
        check(xs == 0, 'no link crosses a wall')
        check(plan.links[#plan.links].closing, 'closing leg back to the start')
        -- every entry/exit sits on an opening that leads somewhere
        local bad = 0
        for id, d in pairs(plan.pieces) do
            if d.E and not d.E.to then bad = bad + 1 end
            if d.X and not d.X.to then bad = bad + 1 end
        end
        check(bad == 0, 'every entry/exit is a doorway into another rect')
    end
end

-- 3. determinism: input order never changes the answer, and encode/decode round-trips
do
    local P = stops_from(HOUSE)
    local A = R.plan(P, nil, {})
    local Q = {}
    for i = #P, 1, -1 do Q[#Q + 1] = P[i] end
    local B = R.plan(Q, nil, {})
    local ba, bb = R.blob(R.encode(A.dec, P)), R.blob(R.encode(B.dec, Q))
    check(ba == bb, 'reversed input -> identical plan (' .. #ba .. ' chars)')
    local dec = R.decode(R.unblob(ba), P)
    check(dec ~= nil and table.concat(dec.order, ',') == table.concat(A.dec.order, ','), 'decode(encode) -> same order')
    -- a peer whose stops are ~1 cm off decodes onto its own stops
    local jit = {}
    for i, p in ipairs(P) do local c = {} for k, v in pairs(p) do c[k] = v end c.cx, c.cz = p.cx + 0.008, p.cz - 0.006 jit[i] = c end
    local dj = R.decode(R.unblob(ba), jit)
    check(dj ~= nil, 'a peer 1 cm off decodes the plan')
    local moved = {}
    for i, p in ipairs(P) do local c = {} for k, v in pairs(p) do c[k] = v end moved[i] = c end
    moved[2].cx = moved[2].cx + 2
    check(R.decode(R.unblob(ba), moved) == nil, 'a moved stop refuses the stale plan')
end

-- 4. options: keep_order, open chain, fixed start, caps
do
    local P = stops_from(HOUSE, { Living = true, Hall = true, Den = true, Kitchen = true })
    local ko = R.plan(P, nil, { keep_order = true, start = 's_Living' })
    local names = {}
    for _, p in ipairs(ko.order) do names[#names + 1] = p.rect.id end
    check(ko ~= nil and ko.dec.start == 's_Living', 'fixed start honoured')
    check(table.concat(names, '>') == 'Living>Hall>Den>Kitchen', 'keep_order keeps the given order: ' .. table.concat(names, '>'))
    local chain = R.plan(P, nil, { loop = false })
    check(chain ~= nil and #chain.links == #chain.order - 1 and not chain.links[#chain.links].closing, 'loop = false: an open chain, no closing leg')
    local loopc = R.plan(P, nil, {})
    check(chain.cost <= loopc.cost + 1e-9, string.format('the open chain never costs more than the loop (%.2f <= %.2f)', chain.cost, loopc.cost))
    local many = {}
    for i = 1, 11 do many[i] = { id = 'x' .. i, name = 'x' .. i, cx = i * 3, cz = 0, yaw = 0, W = 2, L = 2, flex = true } end
    local cap, why = R.plan(many, nil, {})
    check(cap == nil and tostring(why):find('too many') ~= nil, 'over the cap: refused (' .. tostring(why) .. ')')
    local cl = R.clusters(many, { cluster_gap = 0.1 })
    check(#cl == 11, 'clusters: footprints 0.17 m apart with a 0.1 m gap -> 11 venues')
    check(#R.clusters(many, { cluster_gap = 6 }) == 1, 'clusters: 6 m gap -> 1 venue')
end

-- 5. a REAL scan (My House 3): every rect pair connected by doors is routable, no NaN
do
    -- room_1_r0's door and opening lead into space the scan never covered (no `to`): it is an island.
    local P = stops_from(H3)
    local ok, total, island = 0, 0, 0
    for i = 1, #P do for j = 1, #P do if i ~= j then
        local iso = P[i].rect.id == 'room_1_r0' or P[j].rect.id == 'room_1_r0'
        local r = R.route(P, P[i].cx, P[i].cz, P[j].cx, P[j].cz)
        if iso then island = island + ((not r.ok and r.why ~= nil) and 1 or 0)
        else total = total + 1 if r.ok and r.len == r.len and r.len < 1e5 then ok = ok + 1 end end
    end end end
    check(ok == total, string.format('My House 3: %d/%d routes between the 7 connected rects', ok, total))
    check(island == 14, 'My House 3: the unconnected rect (room_1_r0) reports no route, with why (' .. island .. '/14)')
    local plan, why = R.plan(P, nil, {})
    check(plan ~= nil, 'My House 3 tour: ' .. tostring(why or string.format('%d stops, cost %.2f m', plan and #plan.order or 0, plan and plan.cost or 0)))
    check(plan ~= nil and #plan.unreachable == 1 and plan.unreachable[1] == 's_room_1_r0', 'My House 3 tour reports room_1_r0 unreachable: ' .. table.concat(plan and plan.unreachable or {}, ','))
    check(plan ~= nil and #plan.dropped == 1 and plan.dropped[1] == 's_room_4_r0', 'My House 3 tour reports room_4_r0 dropped (its only link is a 0.31 m gap): ' .. table.concat(plan and plan.dropped or {}, ','))
    local Pc = {}
    for _, p in ipairs(P) do if p.rect.id ~= 'room_1_r0' then Pc[#Pc + 1] = p end end
    local pc = R.plan(Pc, nil, {})
    local xs = 0
    for _, l in ipairs(pc and pc.links or {}) do if l.pts == nil then xs = xs + 1 end end
    check(pc ~= nil and xs == 0, string.format('My House 3, connected rects: every link walkable (cost %.2f m)', pc and pc.cost or -1))
end

-- 5b. the park graph: rects with no attraction still carry doors (core's space map via dp_route_graph)
do
    local stops = stops_from(HOUSE, { Living = true, YardC = true })
    local graph = {}
    for _, g in ipairs(stops_from(HOUSE)) do g.graph_only = true graph[#graph + 1] = g end
    local bare = R.plan(stops, nil, {})
    check(bare ~= nil and #bare.unreachable >= 1, 'stops only: Living and YardC cannot reach each other (the doors between are in empty rects)')
    local full = R.plan(stops, nil, { graph = graph })
    local ok = full ~= nil and #full.unreachable == 0
    local xs, hops = 0, 0
    for _, l in ipairs(full and full.links or {}) do xs = xs + crossings(l.pts or {}) hops = hops + #(l.doors or {}) end
    check(ok and xs == 0, string.format('with the park graph: Living <-> YardC through %d doorways, no wall crossed (walk %.2f m)', hops, full and full.cost or -1))
    local r = R.route(stops, 2.5, 2.5, 1.1, 12.0, nil, nil, graph)
    check(r.ok and r.hops >= 4 and crossings(r.pts) == 0, 'dp.route over the park graph: Living -> YardC, ' .. r.hops .. ' doors')
end

-- 6. polyline helpers
do
    local pts = { { x = 0, z = 0 }, { x = 2, z = 0 }, { x = 2, z = 2 } }
    local st = R.resample(pts, 0.5)
    check(math.abs(st.len - 4) < 1e-9 and #st == 9, 'resample: 4 m at 0.5 m -> 9 stations')
    local s, d = R.project(pts, 2.3, 1.0)
    check(math.abs(s - 3) < 1e-9 and math.abs(d - 0.3) < 1e-9, 'project: s = 3, 0.3 m off')
    check(#R.link_arrows(pts, 0.8) == 5, 'link arrows every 0.8 m')
end

-- 6b. v3 open areas (RECT_EDGES_SPEC: all sides unknown): two rects 2 m apart with no link connect straight
do
    local function gym(id, cx)
        local opens = {}
        local e = { { -1, -1, 1, -1, 0, -1 }, { 1, -1, 1, 1, 1, 0 }, { 1, 1, -1, 1, 0, 1 }, { -1, 1, -1, -1, -1, 0 } }
        for _, s in ipairs(e) do
            opens[#opens + 1] = { ax = cx + s[1], az = s[2], bx = cx + s[3], bz = s[4], nx = s[5], nz = s[6], type = 'unknown', kind = 'unknown' }
        end
        return { id = id, name = id, cx = cx, cz = 0, yaw = 0, W = 2, L = 2, flex = true, rect = { id = id, opens = opens, open_area = true } }
    end
    local P = { gym('gA', 0), gym('gB', 4) }
    local r = R.route(P, 0, 0, 4, 0)
    check(r.ok and r.source == 'doors' and r.hops == 0, 'open areas: gA -> gB connect straight (' .. tostring(r.why or r.source) .. ')')
    P[2].rect.open_area = nil
    local r2 = R.route(P, 0, 0, 4, 0)
    check(not r2.ok, 'without open_area the two unlinked rects do not connect (' .. tostring(r2.why) .. ')')
    check(#R.rect_opens(P[1]) == 4, 'an open-area stop offers all four sides')
end

-- 7. the C# embed is current
do
    local f = io.open(HERE .. '/../../Assets/DreamPark/Scripts/Core/DreamParkLuaRoutes.cs', 'r')
    if f then
        local cs = f:read('a') f:close()
        local lib = assert(io.open(HERE .. '/dp_routes.lua')):read('a')
        local fac = assert(io.open(HERE .. '/dp_routes_unity.lua')):read('a')
        check(cs:find(lib, 1, true) ~= nil and cs:find(fac, 1, true) ~= nil, 'DreamParkLuaRoutes.cs embeds the current Lua (else: python3 Tools/routes-offline/embed.py)')
    end
end

print(string.format('\n%d passed, %d failed', passes, fails))
os.exit(fails == 0 and 0 or 1)
